1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	const SPHINX_BASE_SCORE = 2;
8	/**
9	 * The base score covers an army with up to three other monster types; a fourth
10	 * other type is the first that scores extra.
11	 */
12	const OTHER_TYPES_COVERED_BY_BASE_SCORE = 3;
13	const SCORE_PER_EXTRA_TYPE = 2;
14	/**
15	 * Once a Sphinx is scoring extra types the base score no longer applies —
16	 * scoring restarts from 1, so four other types is worth 3 (1 + 2), not 4.
17	 * Confirmed by the "Sphinx, Chimera, Orthrus, Zombie, Hydra → 3 points"
18	 * example; folding this into the base score breaks that test.
19	 */
20	const SCORE_FOR_FIRST_EXTRA_TYPE_STEP = 1;
21	
22	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
23	
24	const countOtherMonsterTypes = (army: Card[], sphinxIndex: number): number =>
25	  new Set(
26	    army.filter((_, index) => index !== sphinxIndex).map((card) => card.monster),
27	  ).size;
28	
29	const scoreOneSphinx = (army: Card[], sphinxIndex: number): number => {
30	  const otherTypeCount = countOtherMonsterTypes(army, sphinxIndex);
31	  if (otherTypeCount <= OTHER_TYPES_COVERED_BY_BASE_SCORE) {
32	    return SPHINX_BASE_SCORE;
33	  }
34	
35	  const extraTypes = otherTypeCount - OTHER_TYPES_COVERED_BY_BASE_SCORE;
36	  return SCORE_FOR_FIRST_EXTRA_TYPE_STEP + SCORE_PER_EXTRA_TYPE * extraTypes;
37	};
38	
39	export const scoreArmy = (army: Card[]): number =>
40	  army.reduce(
41	    (total, card, index) =>
42	      isSphinx(card) ? total + scoreOneSphinx(army, index) : total,
43	    0,
44	  );
